# Powersoft Property - rent schedule write-back on invoice submit.
# Marks the matching rent schedule row Invoiced and links the invoice.

lease_name = doc.get('ps_lease_agreement')

if lease_name:
    row_name = doc.get('ps_schedule_row')
    lease = frappe.get_doc('PS Lease Agreement', lease_name)
    target = None

    if row_name:
        for r in lease.rent_schedule:
            if r.name == row_name:
                target = r
                break

    if not target:
        for r in lease.rent_schedule:
            if not r.sales_invoice:
                gap = frappe.utils.flt(r.total_due) - frappe.utils.flt(doc.grand_total)
                if gap < 0:
                    gap = 0 - gap
                if gap < 0.01:
                    target = r
                    break

    if not target:
        for r in lease.rent_schedule:
            if not r.sales_invoice and r.invoice_status in ('Not Invoiced', 'Overdue'):
                target = r
                break

    if target:
        target.db_set('sales_invoice', doc.name, update_modified=False)
        target.db_set('invoice_status', 'Invoiced', update_modified=False)

    lease.reload()
    billed = ('Invoiced', 'Partly Paid', 'Paid', 'Overdue')
    inv = 0.0
    paid = 0.0
    for r in lease.rent_schedule:
        if r.sales_invoice or r.invoice_status in billed:
            inv = inv + frappe.utils.flt(r.total_due)
        paid = paid + frappe.utils.flt(r.amount_paid)
    bal = inv - paid
    if bal < 0:
        bal = 0.0

    frappe.db.set_value('PS Lease Agreement', lease_name, {'total_invoiced': inv, 'total_paid': paid, 'outstanding_balance': bal}, update_modified=False)

# Powersoft Property - keeps the rent schedule in step with payment.
# Fires whenever a submitted Sales Invoice changes, which includes when a
# Payment Entry reduces its outstanding amount.

lease_name = doc.get('ps_lease_agreement')

if lease_name:
    lease = frappe.get_doc('PS Lease Agreement', lease_name)

    total = frappe.utils.flt(doc.grand_total)
    outstanding = frappe.utils.flt(doc.outstanding_amount)
    settled = total - outstanding

    if outstanding <= 0.005:
        new_status = 'Paid'
    elif settled > 0.005:
        new_status = 'Partly Paid'
    else:
        new_status = 'Invoiced'
        if doc.due_date and frappe.utils.getdate(doc.due_date) < frappe.utils.getdate(frappe.utils.nowdate()):
            new_status = 'Overdue'

    for r in lease.rent_schedule:
        if r.sales_invoice == doc.name:
            r.db_set('invoice_status', new_status, update_modified=False)
            r.db_set('amount_paid', settled, update_modified=False)
            r.db_set('balance', frappe.utils.flt(r.total_due) - settled, update_modified=False)
            if new_status == 'Paid':
                if not r.paid_on:
                    r.db_set('paid_on', frappe.utils.nowdate(), update_modified=False)
            else:
                r.db_set('paid_on', None, update_modified=False)
            break

    lease.reload()
    billed = ('Invoiced', 'Partly Paid', 'Paid', 'Overdue')
    inv = 0.0
    paid = 0.0
    for r in lease.rent_schedule:
        if r.sales_invoice or r.invoice_status in billed:
            inv = inv + frappe.utils.flt(r.total_due)
        paid = paid + frappe.utils.flt(r.amount_paid)
    bal = inv - paid
    if bal < 0:
        bal = 0.0

    frappe.db.set_value('PS Lease Agreement', lease_name, {'total_invoiced': inv, 'total_paid': paid, 'outstanding_balance': bal}, update_modified=False)

# Powersoft Property - when a Payment Entry settles a rent invoice, push the
# result back onto the lease rent schedule. ERPNext updates the invoice's
# outstanding_amount with a direct write, so the Sales Invoice save hooks do
# not fire - this is the reliable place to catch it.

touched = []

for ref in doc.references:
    if ref.reference_doctype != 'Sales Invoice':
        continue
    if not ref.reference_name:
        continue

    si = frappe.get_doc('Sales Invoice', ref.reference_name)
    lease_name = si.get('ps_lease_agreement')
    if not lease_name:
        continue

    total = frappe.utils.flt(si.grand_total)
    outstanding = frappe.utils.flt(si.outstanding_amount)
    settled = total - outstanding
    if settled < 0:
        settled = 0.0

    if outstanding <= 0.005:
        new_status = 'Paid'
    elif settled > 0.005:
        new_status = 'Partly Paid'
    else:
        new_status = 'Invoiced'
        if si.due_date and frappe.utils.getdate(si.due_date) < frappe.utils.getdate(frappe.utils.nowdate()):
            new_status = 'Overdue'

    lease = frappe.get_doc('PS Lease Agreement', lease_name)
    for r in lease.rent_schedule:
        if r.sales_invoice == si.name:
            r.db_set('invoice_status', new_status, update_modified=False)
            r.db_set('amount_paid', settled, update_modified=False)
            r.db_set('balance', frappe.utils.flt(r.total_due) - settled, update_modified=False)
            if new_status == 'Paid':
                if not r.paid_on:
                    r.db_set('paid_on', doc.posting_date, update_modified=False)
            else:
                r.db_set('paid_on', None, update_modified=False)
            break

    if lease_name not in touched:
        touched.append(lease_name)

for lease_name in touched:
    lease = frappe.get_doc('PS Lease Agreement', lease_name)
    billed = ('Invoiced', 'Partly Paid', 'Paid', 'Overdue')
    inv = 0.0
    paid = 0.0
    for r in lease.rent_schedule:
        if r.sales_invoice or r.invoice_status in billed:
            inv = inv + frappe.utils.flt(r.total_due)
        paid = paid + frappe.utils.flt(r.amount_paid)
    bal = inv - paid
    if bal < 0:
        bal = 0.0
    frappe.db.set_value('PS Lease Agreement', lease_name, {'total_invoiced': inv, 'total_paid': paid, 'outstanding_balance': bal}, update_modified=False)

# Powersoft Property - reverses the rent schedule when a rent payment is cancelled.

touched = []

for ref in doc.references:
    if ref.reference_doctype != 'Sales Invoice':
        continue
    if not ref.reference_name:
        continue

    si = frappe.get_doc('Sales Invoice', ref.reference_name)
    lease_name = si.get('ps_lease_agreement')
    if not lease_name:
        continue

    total = frappe.utils.flt(si.grand_total)
    outstanding = frappe.utils.flt(si.outstanding_amount)
    settled = total - outstanding
    if settled < 0:
        settled = 0.0

    if outstanding <= 0.005:
        new_status = 'Paid'
    elif settled > 0.005:
        new_status = 'Partly Paid'
    else:
        new_status = 'Invoiced'
        if si.due_date and frappe.utils.getdate(si.due_date) < frappe.utils.getdate(frappe.utils.nowdate()):
            new_status = 'Overdue'

    lease = frappe.get_doc('PS Lease Agreement', lease_name)
    for r in lease.rent_schedule:
        if r.sales_invoice == si.name:
            r.db_set('invoice_status', new_status, update_modified=False)
            r.db_set('amount_paid', settled, update_modified=False)
            r.db_set('balance', frappe.utils.flt(r.total_due) - settled, update_modified=False)
            if new_status != 'Paid':
                r.db_set('paid_on', None, update_modified=False)
            break

    if lease_name not in touched:
        touched.append(lease_name)

for lease_name in touched:
    lease = frappe.get_doc('PS Lease Agreement', lease_name)
    billed = ('Invoiced', 'Partly Paid', 'Paid', 'Overdue')
    inv = 0.0
    paid = 0.0
    for r in lease.rent_schedule:
        if r.sales_invoice or r.invoice_status in billed:
            inv = inv + frappe.utils.flt(r.total_due)
        paid = paid + frappe.utils.flt(r.amount_paid)
    bal = inv - paid
    if bal < 0:
        bal = 0.0
    frappe.db.set_value('PS Lease Agreement', lease_name, {'total_invoiced': inv, 'total_paid': paid, 'outstanding_balance': bal}, update_modified=False)
